import localFont from 'next/font/local';

// The same Latin subsets previously generated by next/font/google are bundled
// so Production builds do not depend on Google's changing CSS URL format.
export const spaceGrotesk=localFont({
 src:'../../public/mail/fonts/space-grotesk-latin.woff2',weight:'400 700',
 variable:'--schrift-display',display:'swap',
});
export const inter=localFont({
 src:'../../public/mail/fonts/inter-latin.woff2',weight:'400 800',
 variable:'--schrift-text',display:'swap',
});
export const jetbrains=localFont({
 src:'../../public/mail/fonts/jetbrains-mono-latin.woff2',weight:'400 600',
 variable:'--schrift-mono',display:'swap',
});
export const receiptInter=localFont({
 src:'../../public/mail/fonts/inter-latin.woff2',weight:'400 800',
 variable:'--font-receipt-sans',display:'swap',
});
export const receiptMono=localFont({
 src:[
  {path:'../../public/mail/fonts/ibm-plex-mono-latin-500.woff2',weight:'500'},
  {path:'../../public/mail/fonts/ibm-plex-mono-latin-700.woff2',weight:'700'},
 ],variable:'--font-receipt-mono',display:'swap',
});
